// MAIN //

/**
* Legend constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {boolean} [options.aria=true] - boolean indicating whether ARIA attributes should be included in SVG output
* @param {number} [options.clipHeight] - clip height for the legend entries
* @param {number} [options.columnPadding] - horizontal padding (in pixels) between legend columns
* @param {number} [options.columns=1] - number of columns in which to arrange legend entries
* @param {number} [options.cornerRadius] - corner radius for the full legend
* @param {string} [options.description] - legend description
* @param {string} [options.direction='vertical'] - direction of the legend
* @param {Object} [options.encode] - mark encodings for custom legend styling
* @param {string} [options.fill] - name of the scale that maps to a fill color
* @param {string} [options.fillColor] - background fill color for the full legend
* @param {(string|Object)} [options.format] - format specifier for legend labels
* @param {string} [options.formatType] - type of format to use for legend scales which do not have a strict domain data type
* @param {number} [options.gradientLength] - length (in pixels) of the primary axis of a color gradient.
* @param {number} [options.gradientOpacity] - opacity of the color gradient
* @param {string} [options.gradientStrokeColor] - stroke color of the color gradient border
* @param {number} [options.gradientStrokeWidth] - stroke width of the color gradient border
* @param {number} [options.gradientThickness] - thickness (in pixels) of the color gradient
* @param {string} [options.gridAlign='each'] - grid alignment for legend entries
* @param {string} [options.labelAlign] - horizontal text alignment of legend labels
* @param {string} [options.labelBaseline='alphabetic'] - vertical text baseline of legend labels
* @param {string} [options.labelColor] - color of legend labels
* @param {string} [options.labelFont] - font name of legend labels
* @param {number} [options.labelFontSize] - font size of legend labels
* @param {string} [options.labelFontStyle] - font style of legend labels
* @param {(string|number)} [options.labelFontWeight] - font weight of legend labels
* @param {number} [options.labelLimit] - maximum allowed length (in pixels) of legend labels
* @param {number} [options.labelOffset] - offset (in pixels) of legend labels
* @param {number} [options.labelOpacity] - opacity of legend labels
* @param {(boolean|string)} [options.labelOverlap=true] - strategy for resolving overlapping legend labels
* @param {number} [options.labelSeparation=0] - minimum separation between legend label bounding boxes
* @param {number} [options.legendX] - custom x position for the legend group
* @param {number} [options.legendY] - custom y position for the legend group
* @param {number} [options.offset] - offset (in pixels) by which to displace the legend from the data rectangle and axes
* @param {string} [options.opacity] - name of the scale that maps to an opacity value
* @param {string} [options.orient='right'] - legend orientation
* @param {number} [options.padding] - padding (in pixels) between legend border and content of the legend group
* @param {number} [options.rowPadding] - vertical padding (in pixels) between legend symbol legend entries
* @param {string} [options.shape] - name of the scale that maps to a shape value
* @param {string} [options.size] - name of the scale that maps to a size value
* @param {string} [options.stroke] - name of the scale that maps to a stroke color
* @param {string} [options.strokeColor] - name of the scale that maps to a stroke color
* @param {string} [options.strokeDash] - name of the scale that maps to a stroke dash value
* @param {string} [options.strokeWidth] - name of the scale that maps to a stroke width value
* @param {NumericArray} [options.symbolDash=[]] - stroke dash for legend symbols
* @param {number} [options.symbolDashOffset] - pixel offset at which to start the symbol stroke dash array
* @param {string} [options.symbolFillColor] - fill color of legend symbols
* @param {number} [options.symbolLimit] - maximum number of entries for a symbol legend
* @param {number} [options.symbolOffset] - horizontal pixel offset for legend symbols
* @param {number} [options.symbolOpacity] - opacity of legend symbols
* @param {number} [options.symbolSize] - default symbol area size (in squared pixels)
* @param {string} [options.symbolStrokeColor] - stroke color of legend symbols
* @param {number} [options.symbolStrokeWidth] - stroke width of legend symbols
* @param {string} [options.symbolType] - default symbol shape type for legend entries
* @param {(number|string|Object)} [options.tickCount] - desired number of tick values for quantitative legends
* @param {number} [options.tickMinStep] - minimum desired step between tick values
* @param {(string|Array<string>)} [options.title=['']] - legend title
* @param {string} [options.titleAlign] - horizontal text alignment of the legend title
* @param {(string|null)} [options.titleAnchor=null] - legend title anchor position
* @param {string} [options.titleBaseline='alphabetic'] - vertical text baseline of the legend title
* @param {string} [options.titleColor] - color of the legend title
* @param {string} [options.titleFont] - font name of the legend title
* @param {number} [options.titleFontSize] - font size of the legend title
* @param {string} [options.titleFontStyle] - font style of the legend title
* @param {(string|number)} [options.titleFontWeight] - font weight of the legend title
* @param {number} [options.titleLimit] - maximum allowed length (in pixels) of the legend title
* @param {number} [options.titleLineHeight] - line height (in pixels) for multi-line title text
* @param {number} [options.titleOpacity] - opacity of the legend title
* @param {string} [options.titleOrient='top'] - orientation of the legend title
* @param {number} [options.titlePadding] - padding (in pixels) between the legend title and entries
* @param {string} [options.type] - legend type
* @param {Array} [options.values] - explicit set of legend values
* @param {number} [options.zindex=0] - integer z-index indicating the layering of the legend group relative to other axis, mark, and legend groups
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide at least one legend scale property
* @throws {Error} must provide valid options
* @returns {Legend} legend instance
*
* @example
* var legend = new Legend({
*     'fill': 'colorScale'
* });
* // returns <Legend>
*/
function Legend( options ) {
	var opts;
	var keys;
	var flg;
	var v;
	var k;
	var i;
	if ( !( this instanceof Legend ) ) {
		return new Legend( options );
	}
	EventEmitter.call( this );
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Check for required properties (at least one scale reference must be provided)...
	for ( i = 0; i < PROPS.length; i++ ) {
		if ( hasProp( options, PROPS[ i ] ) ) {
			flg = true;
			break;
		}
	}
	if ( !flg ) {
		throw new TypeError( 'invalid argument. Options argument must specify at least one legend scale property (e.g., fill, opacity, shape, size, stroke, or strokeDash).' );
	}
	// Resolve the default configuration:
	opts = defaults( options.direction || 'vertical' );

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

